void another_world_vm_state::changePalette(uint8_t paletteId)
{
	const uint8_t *colors = (const uint8_t *) membank("palette_bank")->base();
	uint8_t r, g, b;

	for (int i = 0; i < NUM_COLORS; ++i)
	{
