	const uint8_t *font = memregion("chargen")->base();

	for (int j = 0; j < 8; j++)
	{
		uint8_t row = font[(character - ' ') * 8 + j];
		for (int i = 0; i < 8; i++)
		{
			if (row & 0x80)
				drawPoint(color, x+i, y+j);

			row <<= 1;
		}
	}
